// Compact URL shortener: counter+base62, cache-aside, custom alias, 301/302, async analytics.
// Each class below would be its own file in a real project.
package com.bank.shortener;

import java.util.logging.*;

public class ShortenerDemo {

    private static final Logger log = Logger.getLogger("Shortener");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RangeCounter counter = new RangeCounter(1000);
        LinkStore store = new LinkStore();
        ClickRecorder analytics = new ClickRecorder();

        // Create: statement URL for Rajesh → unique counter → base62 code (no collision)
        long id1 = counter.next();
        String code1 = Base62.encode(id1);
        store.save(code1, "https://bank.in/statements/SAV2001/oct-2026-very-long-token", 301);
        log.info(() -> "short bank.in/" + code1 + " → Rajesh statement (301 permanent)");

        // Create: campaign URL with a 302 so every click is counted + destination changeable
        long id2 = counter.next();
        String code2 = Base62.encode(id2);
        store.save(code2, "https://bank.in/offers/home-loan-diwali", 302);
        log.info(() -> "short bank.in/" + code2 + " → campaign (302 temporary, analytics on)");

        // Custom alias with uniqueness check
        boolean ok = store.saveAlias("rajesh-loan", "https://bank.in/offers/personal-loan", 302);
        log.info(() -> "custom alias 'rajesh-loan' reserved = " + ok);

        // Resolve (redirect) path: cache-first, analytics off the hot path
        resolve(store, analytics, code2);
        resolve(store, analytics, code2);   // second click: cache hit
        resolve(store, analytics, "rajesh-loan");
    }

    static void resolve(LinkStore store, ClickRecorder analytics, String code) {
        LinkStore.Link link = store.resolve(code);       // cache-aside: cache → DB on miss
        if (link == null) { log.warning(() -> "404 unknown code " + code); return; }
        analytics.recordAsync(code);                      // async: does NOT block redirect
        log.info(() -> "HTTP " + link.redirectType + " redirect " + code + " → " + link.longUrl);
    }
}

// ─── id/RangeCounter.java ───  per-server range allocation (no central bottleneck)
class RangeCounter {
    private static final Logger log = Logger.getLogger("Shortener");
    private final int rangeSize;
    private long current = 0, rangeEnd = 0;
    private static long GLOBAL = 100_000;                 // simulates the central allocator

    RangeCounter(int rangeSize) { this.rangeSize = rangeSize; }

    synchronized long next() {
        if (current >= rangeEnd) {                        // fetch a new block rarely
            current = GLOBAL;
            GLOBAL += rangeSize;
            rangeEnd = GLOBAL;
            log.fine(() -> "fetched new id block [" + current + "," + rangeEnd + ")");
        }
        return current++;                                 // mint locally, no collision ever
    }
}

// ─── codec/Base62.java ───  pack a counter into a short code
class Base62 {
    private static final String A = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    static String encode(long n) {
        if (n == 0) return "0";
        StringBuilder sb = new StringBuilder();
        while (n > 0) { sb.append(A.charAt((int)(n % 62))); n /= 62; }
        return sb.reverse().toString();
    }
}

// ─── store/LinkStore.java ───  mapping store + cache-aside + uniqueness
class LinkStore {
    private static final Logger log = Logger.getLogger("Shortener");
    static class Link { final String longUrl; final int redirectType;
        Link(String u, int t){ longUrl=u; redirectType=t; } }

    private final java.util.Map<String, Link> db = new java.util.concurrent.ConcurrentHashMap<>();   // "database"
    private final java.util.Map<String, Link> cache = new java.util.concurrent.ConcurrentHashMap<>(); // Redis

    void save(String code, String longUrl, int redirectType) {
        db.putIfAbsent(code, new Link(longUrl, redirectType));   // unique index = final arbiter
    }
    boolean saveAlias(String alias, String longUrl, int redirectType) {
        return db.putIfAbsent(alias, new Link(longUrl, redirectType)) == null;  // reject if taken
    }
    Link resolve(String code) {
        Link cached = cache.get(code);
        if (cached != null) { log.fine(() -> "cache HIT " + code); return cached; }  // hot path
        Link fromDb = db.get(code);
        if (fromDb != null) cache.put(code, fromDb);             // populate cache on miss
        log.fine(() -> "cache MISS " + code + " → DB");
        return fromDb;
    }
}

// ─── analytics/ClickRecorder.java ───  record clicks OFF the redirect hot path
class ClickRecorder {
    private static final Logger log = Logger.getLogger("Shortener");
    private final java.util.Map<String, Integer> counts = new java.util.concurrent.ConcurrentHashMap<>();
    void recordAsync(String code) {
        // real impl: publish a click event to Kafka; a consumer aggregates later
        counts.merge(code, 1, Integer::sum);
        log.fine(() -> "click recorded " + code + " total=" + counts.get(code));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
